package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import org.springframework.boot.CommandLineRunner;import org.springframework.stereotype.Component;import java.util.*;import java.nio.charset.StandardCharsets;
/** Idempotent migration of the legacy embedded user booking summaries. */
@Component public class BookingMigration implements CommandLineRunner {
 private final UserRepository users;private final BookingRepository bookings;
 public BookingMigration(UserRepository u,BookingRepository b){users=u;bookings=b;}
 public void run(String...args){for(Users user:users.findAll()){if(user.getBookings()==null||user.getBookings().isEmpty())continue;boolean changed=false;for(Users.Booking old:user.getBookings()){if(old.getBookingId()==null||old.getType()==null)continue;Booking.Type type;if("flight".equalsIgnoreCase(old.getType()))type=Booking.Type.FLIGHT;else if("hotel".equalsIgnoreCase(old.getType()))type=Booking.Type.HOTEL;else continue;java.time.LocalDate date;try{date=java.time.LocalDate.parse(old.getDate());}catch(Exception ex){date=java.time.LocalDate.now();}Booking canonical=null;if(old.getBookingDocumentId()!=null)canonical=bookings.findById(old.getBookingDocumentId()).orElse(null);String key=UUID.nameUUIDFromBytes((user.getId()+":"+old.getBookingId()+":"+old.getDate()+":"+old.getType()).getBytes(StandardCharsets.UTF_8)).toString();if(canonical==null)canonical=bookings.findById(key).orElse(null);if(canonical==null){final java.time.LocalDate bookingDate=date;canonical=bookings.findByUserId(user.getId()).stream().filter(x->x.getBookingType()==type&&old.getBookingId().equals(x.getProductId())&&bookingDate.equals(x.getBookingDate())).findFirst().orElse(null);}if(canonical==null){canonical=new Booking();canonical.setId(key);canonical.setUserId(user.getId());canonical.setBookingType(type);canonical.setProductId(old.getBookingId());canonical.setQuantity(old.getQuantity());canonical.setTotalPrice(old.getTotalPrice());canonical.setBookingDate(date);canonical.setCreatedAt(date.atStartOfDay(java.time.ZoneOffset.UTC).toInstant());if(old.getStatus()!=null)try{canonical.setStatus(Booking.Status.valueOf(old.getStatus()));}catch(IllegalArgumentException ignored){}canonical=bookings.save(canonical);}if(!Objects.equals(old.getBookingDocumentId(),canonical.getId())){old.setBookingDocumentId(canonical.getId());changed=true;}String status=canonical.getStatus()==null?null:canonical.getStatus().name();if(!Objects.equals(old.getStatus(),status)){old.setStatus(status);changed=true;}if(old.getQuantity()!=canonical.getQuantity()){old.setQuantity(canonical.getQuantity());changed=true;}if(Double.compare(old.getTotalPrice(),canonical.getTotalPrice())!=0){old.setTotalPrice(canonical.getTotalPrice());changed=true;}}if(changed)users.save(user);}}
}
